    def has_clear_path_horizontal(r, c, target_r):
        """Check if row r, col c has clear horizontal path to column where inp[target_r][some_col] == 8"""
        # Check same row first
        if inp[r][c] == 8:
            return True

        # Look left along row r
        for dc in range(-1, -W-1, -1):
            nc = c + dc
            if nc < 0:
                break
            val = inp[r][nc]
            if val == 8:
                return True
            if val != 0 and val != 2:  # Something else blocks
                break  # Can't pass through non-0,non-2,non-8

        # Look right
        for dc in range(1, W-c):
            nc = c + dc
            if nc >= W:
                break
            val = inp[r][nc]
            if val == 8:
                return True
            if val != 0 and val != 2:
                break

        return False

    def has_clear_path_vertical(r, c, target_c):
        """Same for vertical"""
        # Look up
        for dr in range(-1, -H+1, -1):
            nr = r + dr
            if nr < 0:
                break
            val = inp[nr][c]
            if val == 8:
                return True
            if val != 0 and val != 2:
                break

        # Look down
        for dr in range(1, H-r):
            nr = r + dr
            if nr >= H:
                break
            val = inp[nr][c]
            if val == 8:
                return True
            if val != 0 and val != 2:
                break

        return False

    def has_clear_orthogonal_line_to_8(r, c):
        """Check if cell has horizontal or vertical line-of-sight to any 8"""
        for sr, sc in start_8s:
            # Same row?
            if r == sr:
                blocked = False
                # Check left
                for nc in range(sc-1, c-1, -1):
                    val = inp[r][nc]
                    if val == 8:
                        return True
                    if val == 0:
                        continue
                    blocked = True
                    break
                if not blocked:
                    # Check right  
                    for nc in range(sc+1, c+1):
                        val = inp[r][nc]
                        if val == 8:
                            return True
                        if val == 0:
                            continue
                        blocked = True
                        break
            # Same column?
            elif c == sc:
                blocked = False
                for nr in range(sr-1, r-1, -1):
                    val = inp[nr][c]
                    if val == 8:
                        return True
                    if val == 0:
                        continue
                    blocked = True
                    break
                if not blocked:
                    for nr in range(sr+1, r+1):
                        val = inp[nr][c]
                        if val == 8:
                            return True
                        if val == 0:
                            continue
                        blocked = True
                        break
        return False

    matches = 0
    mismatches = []

    for r in range(H):
        for c in range(W):
            if inp[r][c] == 0:
                expected = has_clear_orthogonal_line_to_8(r, c)
                actual = out_exp[r][c] == 8

                if expected != actual:
                    mismatches.append(((r,c), f"expected={expected},actual={actual}"))
                else:
                    matches += 1

    print(f"\nMatches: {matches}/{len(inp)*len(inp[0])}")
    print(f"Mismatches: {len(mismatches)}")

    for m in mismatches[:20]:
        print(f"  {m}")

